/** Dua Qunoot (Sheikh Mishary Al-Afasy). Text transcribed from the Ommah TV video; timings follow its audio. Not verified, see REVIEW.md. */
object QunootData {
    val lines = listOf(
        DuaLine(500L, "اللَّهُمَّ اهْدِنَا فِيمَنْ هَدَيْتَ", "O Allah, guide us among those whom You guided,"),
        DuaLine(4500L, "وَعَافِنَا فِيمَنْ عَافَيْتَ", "relieve us from sickness among those whom You relieved,"),
        DuaLine(8500L, "وَتَوَلَّنَا فِيمَنْ تَوَلَّيْتَ", "be an ally to us along with those whom You have allied with,"),
        DuaLine(12500L, "وَبَارِكْ لَنَا فِيمَا أَعْطَيْتَ", "and bless us with that which You have bestowed upon us,"),
        DuaLine(16500L, "وَقِنَا شَرَّ مَا قَضَيْتَ", "and save us from the evil of what You have decreed,"),
        DuaLine(20000L, "إِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ", "for You are the One Who orders (ordains) and not the One Who is ordered (ordained for),"),
        DuaLine(24500L, "إِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، وَلَا يَعِزُّ مَنْ عَادَيْتَ", "and he is not humiliated whom You have befriended, nor is he honoured who is Your enemy,"),
        DuaLine(32500L, "تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ", "Blessed are You, O Lord, and Exalted,"),
        DuaLine(37500L, "لَكَ الْحَمْدُ عَلَى مَا قَضَيْتَ", "to You is all the praise for what You have decreed,"),
        DuaLine(41000L, "وَلَكَ الشُّكْرُ عَلَى مَا أَعْطَيْتَ", "all praise is Yours for what You decree,"),
        DuaLine(45500L, "نَسْتَغْفِرُكَ اللَّهُمَّ مِنْ جَمِيعِ الذُّنُوبِ وَالْخَطَايَا وَنَتُوبُ إِلَيْكَ", "we ask Your forgiveness, O Allah, from all sins and turn to You in repentance."),
        DuaLine(54500L, "اللَّهُمَّ اقْسِمْ لَنَا مِنْ خَشْيَتِكَ مَا تَحُولُ بِهِ بَيْنَنَا وَبَيْنَ مَعْصِيَتِكَ", "O Allah, apportion to us such fear as should serve as a barrier between us and acts of disobedience,"),
        DuaLine(64000L, "وَمِنْ طَاعَتِكَ مَا تُبَلِّغُنَا بِهِ جَنَّتَكَ", "and such obedience as will take us to Your Jannah,"),
        DuaLine(70000L, "وَمِنَ الْيَقِينِ مَا تُهَوِّنُ بِهِ عَلَيْنَا مَصَائِبَ الدُّنْيَا", "and such as will make easy for us to bear the calamities of this world,"),
        DuaLine(78000L, "وَمَتِّعْنَا اللَّهُمَّ بِأَسْمَاعِنَا", "O Allah! Let us enjoy our hearing,"),
        DuaLine(83000L, "وَأَبْصَارِنَا", "and our sight,"),
        DuaLine(86000L, "وَقُوَّاتِنَا أَبَدًا مَا أَبْقَيْتَنَا", "and our power, as long as You keep us alive,"),
        DuaLine(92000L, "وَاجْعَلْهُ الْوَارِثَ مِنَّا", "and allow this to remain until our death,"),
        DuaLine(96000L, "وَاجْعَلْ ثَأْرَنَا عَلَى مَنْ ظَلَمَنَا", "O Allah! Avenge us over those who have oppressed us,"),
        DuaLine(101000L, "وَانْصُرْنَا عَلَى مَنْ عَادَانَا", "and support us against those who are hostile to us,"),
        DuaLine(105500L, "وَلَا تُسَلِّطْ عَلَيْنَا بِذُنُوبِنَا مَنْ لَا يَخَافُكَ فِينَا وَلَا يَرْحَمُنَ", "and let not those rule over us who do not fear You and show no mercy to us."),
        DuaLine(114500L, "اللَّهُمَّ أَعِزَّ الإِسْلَامَ وَالْمُسْلِمِينَ", "O Allah! Raise the standing of Islam and the Muslims,"),
        DuaLine(120500L, "وَأَذِلَّ الشِّرْكَ وَالْمُشْرِكِينَ", "and degrade the Shirk and the Mushrikeen [polytheists],"),
        DuaLine(124500L, "وَدَمِّرْ أَعْدَآءَ الدِّينِ", "destroy the enemies of the Deen,"),
        DuaLine(129000L, "وَاحْمِ حَوْزَةَ الإِسْلَامِ", "and protect the lands of Islam,"),
        DuaLine(132000L, "وَاجمَع كَلِمَةَ المُسلِمِين علي الحَقّ يا رَبّ العَالمِين", "and gather the words of all the Muslims on the words of truth, O Lord of Mankind!"),
        DuaLine(139000L, "اللّهمّ أبرم لِهَذِهِ الأمّة امراً رَشِيدا", "O Allah! Grant this Ummah a guiding command,"),
        DuaLine(145500L, "يُعزّ فيه أهل الطَاعَة", "by which those who obey You are strengthened,"),
        DuaLine(149000L, "ويُذلّ فيه أهل المَعصِية", "and those who disobey You are degraded,"),
        DuaLine(152500L, "ويؤمر فِيه بِالمَعرُوف", "and in which the good is commanded,"),
        DuaLine(156500L, "ويُنهى فيه عَن المُنكر", "and the evil is forbidden [with clear knowledge],"),
        DuaLine(160500L, "بِرحمَتك يَا أرحَم الرّاحِمين", "bless us with staying away from it, with Your mercy, O Most Merciful!"),
        DuaLine(165500L, "آللَّهُمَّ انّا نَسْالُكَ بِكُلِّ اسْمٍ هُوَلَكَ", "O Allah! We ask You by every Attribute of Yourself,"),
        DuaLine(171000L, "سَمَّيْتَ بِهِ نَفْسَكَ", "which You called Yourself,"),
        DuaLine(173500L, "اَوْآنْزَلْتَهُ فِى كِتَابِكَ", "or revealed in Your Book,"),
        DuaLine(177500L, "اَوْ عَلَّمْتَهُ اَحَدًا مِنْ خَلْقِكَ", "or taught any of Your creation,"),
        DuaLine(181500L, "اَوْاسْتَاثَرْتَ بِهِ فِى عِلْمِ ا لْغَيْبِ عِنْدَكَ", "or kept exclusively in the knowledge of the Beyond with You,"),
        DuaLine(186500L, "اَنْ تَجْعَلَ الْقُرانَ الْعَظِيمَ رَبِيعَ قُلُوبِنَا", "that You make the Quran the spring of our hearts,"),
        DuaLine(193000L, "وَنُورَ صُدُورِنَا", "the light of our bosoms,"),
        DuaLine(196000L, "وَجَلاَءَ اَحْزَانِنَا", "the expelling of our sadness,"),
        DuaLine(199500L, "وَذهَابَ هُمُومِنَا وَ غُمُومِنَا", "and the taking away of our worries and depression."),
        DuaLine(204000L, "آللَّهُمَّ ذَكِّرْنَا مِنْهُ مَا نَسِينَا", "O Allah, remind us of what we forgot of it,"),
        DuaLine(209500L, "وَعَلِّمْنَا مِنْهُ مَا جَهِلْنَا", "teach us of it what we have not learned,"),
        DuaLine(214000L, "وَارزُقنَا تِلاوَته اناء اللّيل واطرَافَ النّهار", "and grant us its recitation during the depths of the night and the edges of the day,"),
        DuaLine(222500L, "عَلى الوَجهِ الّذِي يُرضِيك عنّا", "in the manner that pleases You."),
        DuaLine(228000L, "اللّهمّ اغفِر لَنَا وارحَمنا واعتِق رِقَابنا مِن النّار", "O Allah! Forgive us and have mercy upon us and free our necks from the Fire."),
        DuaLine(252000L, "اللّهمّ اغْفر لَنا وَلوالدِينَا", "O Allah! Forgive us and our parents,"),
        DuaLine(263500L, "ولأزواجِنا وذرّيّاتنا", "our wives and our children,"),
        DuaLine(268000L, "و ارحَامِنَا واصحَابنَا", "and have mercy on us and our companions,"),
        DuaLine(272500L, "ومشَايخنا وحكّامنا", "and our clerics and judges,"),
        DuaLine(277000L, "ومَن اوصَانا واستوصَانا بدعَاء الخَير", "and those who have instructed us to pray for goodness,"),
        DuaLine(282500L, "ولِمَن لَه حَق عَلينَا يَا كرِيم", "and who have rights over us, O Most Generous!"),
        DuaLine(287500L, "اللّهم انت الله لاالَه الّا انت", "O Allah! You are [our] Allah, there is none to be worshipped except You,"),
        DuaLine(296000L, "انت الغنيّ ونَحنُ الفُقَراء", "You are Rich, and we are Poor!"),
        DuaLine(313000L, "انزل عَلينا الغَيثَ وَلا تَجْعلنَا مِن القَانِطِين", "O Allah! Send down rain as a blessing to us from You, and do not let us be of those who despair of Your mercy,"),
        DuaLine(327500L, "اللّهمّ أغثنا", "O Allah, send us rain [relieve us],"),
        DuaLine(337500L, "اللّهمّ سُقيا رَحمَة", "O Allah! Shower us with Your mercy,"),
        DuaLine(341000L, "لَا سقيا عَذاب وَلَا هَدم وَلَا غَرَق", "not with [Your] punishment, nor an end [with] no purpose."),
        DuaLine(348000L, "اللّهمّ إنَّا خَلق مِن خَلقِك", "O Allah! We are just creatures from Your creations,"),
        DuaLine(352500L, "فَلَا تمنَع عنّا بِذُنوبنَا فَضْلك يَا كَرِيم", "please, do not leave us with our sins, O Most Generous!"),
        DuaLine(360500L, "يَا مَن لا يَفد الوَافِدون عَلى أكرَمَ مِنه", "O He none more generous than whom is reached by the reachers,"),
        DuaLine(367000L, "وَلَا يَجد القَاصِدُونَ أرحَم مِنه", "and none more merciful than whom is found by the aimers!"),
        DuaLine(372000L, "يَاخَير مَن خَلا بِه وَحيدٌ", "O Best of those with whom the lonely are alone,"),
        DuaLine(377500L, "وَيَا خَير من أوَى إليه طَريدٌ", "O Best of those with whom outcasts seek haven!"),
        DuaLine(383000L, "إلى سِعَة عَفوكَ مددنا ايدينا", "toward the expanse of Your pardon have we extended our hands,"),
        DuaLine(389000L, "فَلَا تُولنا الحِرمَان", "show us no deprivation,"),
        DuaLine(393500L, "وَلَا تُبلِنَا بِالخَيبَة وَالخُسرَان", "and afflict us not with disappointment and loss!"),
        DuaLine(400500L, "وَلَا تردّنَا بَعدَ هَاذَا الدُّعَاء خائبين", "and do not return or reject [our supplications], and thus make us return without hope,"),
        DuaLine(407500L, "وَلَا عَن بَابِ جُودِك مَطرُودِين", "nor from the door of Your generosity are we expelled,"),
        DuaLine(412000L, "يا جواد يا كريم", "O Ever-Giving One! O Compassionate!"),
        DuaLine(415500L, "آللَّهُمَّ لَا تَدَعْ لَنَا فِي مقَامِنا هَاذَا ذنبَا اِلّا غَفَرْتَه", "O Allah! Do not leave a sin of ours in this position, except that You forgive it,"),
        DuaLine(424000L, "وَلَا هَمًّا اِلَا فَرَّجْتَه", "nor any concern except that You create for it an opening,"),
        DuaLine(428000L, "وَلَا كَرْباً إِلَّا نَفَّسْتَه", "and all the grief but You relieve it,"),
        DuaLine(432500L, "وَلَا دَيْناً اِلَّا قَضَيْتَه", "a debt without having it paid back,"),
        DuaLine(436000L, "وَلَا مَرِيضًا إِلّا شَفيتَه", "an illness unhealed,"),
        DuaLine(448500L, "وَلَا مُبْتَلًى إِلَّا عَافَيْتَهُ", "a handicap without relief,"),
        DuaLine(453000L, "وَلَا ضَالاً إلّا هدَيتَه", "and those lost but to guide them,"),
        DuaLine(458000L, "وَلَا ولداً الاّ اصلَحتَه", "and make our sons good believers,"),
        DuaLine(462500L, "وَلَا شَهِيدا الاّ تَقبَّلته", "and not a martyr, but You accepted [his cause],"),
        DuaLine(467000L, "وَلَا حَاجَة مِن حَوَائِجِ الدُّنيَا والآخِرَة", "and [do not leave] a need from the needs of the Dunya or the Aakhirah"),
        DuaLine(473000L, "هِي لَكَ رِضاً وَلَنَا فِيها صَلَاح", "without providing for it with ease, and no need [of ours] with which You are pleased,"),
        DuaLine(478000L, "إلّا أعنتنا عَلى قَضائِهَا", "and is good for us in this world and the hereafter,"),
        DuaLine(482500L, "ويسرّتها بِرَحمَتكَ يَا أرحَم الرّاحِمين", "and [do not leave] any of our needs unfulfilled, by Your mercy, O Most Merciful of the merciful!"),
        DuaLine(490000L, "اللّهمّ إنّا نَسألُك فِعلَ الخَيرَات", "O Allah, we ask You [to guide us to] doing good deeds,"),
        DuaLine(496500L, "وَترك المُنكَرَات", "and to [help us] leave evil deeds,"),
        DuaLine(499000L, "وحُبّ المَسَاكِين", "and loving the needy."),
        DuaLine(502000L, "وان تَغفِر لَنَا وَترحَمنَا وتتُوبَا عَلَينَا", "And [we ask You] to forgive us and show us mercy and accept our repentance,"),
        DuaLine(508000L, "وَإذَا أَرَدتَ فِتْنَة في قَوْمٍ فَقبِضنا اليك غَيرَ مَفتُونين", "and when You will to afflict some people [around us] with a [destructive] trial, take our lives without being tried [in faith]."),
        DuaLine(516000L, "اللّهمّ انّا نَسْأَلكَ حُبَّكَ", "O Allah! We beseech You [to grant us] the love of You,"),
        DuaLine(520500L, "وَحُبَّ مَنْ يُحِبُّكَ", "and of those who love You,"),
        DuaLine(523000L, "وَحُبَّ عَمَل يُقَرّبُنا اِلَى حُبّكَ", "and of all deeds that can bring us nearer to Your love."),
        DuaLine(528000L, "اللّهمّ اغفر لجميع مَوتَى المُسلمين", "O Allah! Forgive all the dead Muslims,"),
        DuaLine(534000L, "الّذِينَ شَهدوا لَكَ بِالوَحْدَانيّة", "those believing that there is no god other than You"),
        DuaLine(539500L, "وَلنَبيّك بِالرّسَالَة", "and Your Prophet Muhammad, his message,"),
        DuaLine(543000L, "وَمَاتُوا عَلى ذَلِك", "and died on that [cause]."),
        DuaLine(546000L, "اللّهُمِّ اغْفِرْ لَهُم وَارْحَمْهم", "O Allah! Forgive their sins and have mercy on them,"),
        DuaLine(550500L, "وَعافهم وَاعْفُ عَنْهم", "keep them safe and pardon them,"),
        DuaLine(553000L, "وَ أَكْرِمْ نُزُلَهمْ", "honour the place where they settle,"),
        DuaLine(556500L, "وَوَسِّعْ مُدْخَلَهمْ", "and make their entrance wide,"),
        DuaLine(559000L, "وَاغْسِلْهمْ بِالْماءِ وَالثَّلْج وَالْبَرَدْ", "wash them with water and snow and hail,"),
        DuaLine(565000L, "وَنَقِّهم من الذُّنوبِ والْخطايا كَما ينقَّ الثَّوْبُ الأَبْيَضُ مِنَ الدَّنَسْ", "and cleanse them of sin as a white garment is cleansed of dirt."),
        DuaLine(574000L, "وَارحَمنَا اللّهمّ بِرَحمَتِك اذَا صِرنَا الَى مَا صَارُوا إليه", "We ask You to have mercy on us as well, when we become like them,"),
        DuaLine(582500L, "تَحتَ الجَنادِلِ والتُّرابِ وَحْدَنَا", "under earth, lonely and helpless."),
        DuaLine(588000L, "اللّهمّ آنس وَحشَتنَا فِى القُبُور", "O Allah! Divert our restlessness in the grave into peace,"),
        DuaLine(593000L, "وامنًّا يَومَ العَرضِ وَالنُّشور", "and secure us [until] the Day of the Resurrection,"),
        DuaLine(598000L, "يَا عَزِيزُ يَا غَفُور", "The Mighty, The All-Forgiving."),
        DuaLine(602000L, "اللّهمّ إنَّا نَسألُكَ مِنَ الخَيرِ كُلِّه، عَاجِلِهِ وَآجِلِه", "O Allah! We ask You everything that is good, in this world and in the hereafter,"),
        DuaLine(610000L, "مَا عَلِمنَا مِنهُ وَمَا لَم نَعلَم", "whether we know it or not,"),
        DuaLine(614000L, "وَنَعُوذُ بِكَ مِنَ الشَّرِّ كُلِّه، عَاجِلِه وَآجِلِه", "and seek Your protection from everything that is bad, in this world and the hereafter,"),
        DuaLine(620000L, "مَا عَلِمنَا مِنهُ وَمَا لَم نَعلَم", "whether we know it or not,"),
        DuaLine(624000L, "اللّهمّ إنَّا نَسألُك الجنّه", "O Allah! We seek from You Jannah [Paradise],"),
        DuaLine(639500L, "وَنَعوذُ بِكَ مِنَ النَّار", "we seek refuge from You from the Hellfire."),
        DuaLine(643500L, "اللّهمّ أجِرنَا مِنَ النَّار", "O Allah! Save us from the fire."),
        DuaLine(658500L, "اللّهمَّ انّا نعوذ بِرِضَاكَ من سَخَطِك", "O Allah! We seek refuge in Your being pleased with us against Your wrath,"),
        DuaLine(663500L, "وَبِمُعَافَاتِكَ مِن عُقُوبَتِكْ", "and in Your pardon against Your punishment,"),
        DuaLine(667000L, "وبك مِنكَ لَا نحْصِي ثَنَاءً عَلَيْكَ أنتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ", "and in You against You. We cannot count the praise You are worthy of; You are as You have praised Yourself."),
        DuaLine(675500L, "و صلّي اللَّهمَّ عَلَي نَبيّنَا مُحمّد وَعَلَي آلِهِ وَصَحبِه اجمَعِين", "and send Your prayers, peace and blessings on our Prophet Muhammad and on his family, companions and followers."),
    )
}
